    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    camera_patches = image_patch.find("camera")

    if not man_patches or not camera_patches:
        return image_patch

    # Sort men by their horizontal center position
    man_patches.sort(key=lambda p: p.horizontal_center)

