def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    pitchers = image_patch.find("pitcher")
    gloves = image_patch.find("glove")
    balls = image_patch.find("ball")

    if not pitchers or not gloves or not balls:
        return image_patch

    pitcher_gloves = [(p, g) for p in pitchers for g in gloves if p.overlaps_with(g.left, g.lower, g.right, g.upper)]

    if not pitcher_gloves:
        return image_patch

    pitcher_glove_pairs = []
    for pitcher, glove in pitcher_gloves:
        ball_distances = [distance_3d(b, pitcher) for b in balls if b.overlaps_with(pitcher.left, pitcher.lower, pitcher.right, pitcher.upper)]
        if ball_distances:
            pitcher_glove_pairs.append((pitcher, glove, min(ball_distances)))

    if not pitcher_glove_pairs:
        return image_patch

    _, _, min_distance = min(pitcher_glove_pairs, key=lambda x: x[2])
    closest_pair = next(x for x in pitcher_glove_pairs if x[2] == min_distance)

    return closest_pair[0]

